-- Additive scheduling and private team workspace; no existing records removed.
CREATE TABLE IF NOT EXISTS cv_workshop_slots(id TEXT PRIMARY KEY,artist_id TEXT NOT NULL,country TEXT NOT NULL,city TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'UTC',capacity INTEGER NOT NULL,price_usd REAL NOT NULL,confirmed_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_workshop_slots_location ON cv_workshop_slots(status,country,start_at);
CREATE TABLE IF NOT EXISTS cv_group_requests(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,member_id TEXT,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,country TEXT NOT NULL,city TEXT NOT NULL,craft TEXT NOT NULL,artist_id TEXT NOT NULL DEFAULT '',date TEXT NOT NULL,people INTEGER NOT NULL,currency TEXT NOT NULL,slot_id TEXT NOT NULL DEFAULT '',guide_usd REAL,note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new',assigned_to TEXT NOT NULL DEFAULT 'elferah',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_group_requests_queue ON cv_group_requests(status,assigned_to,created_at);
CREATE TABLE IF NOT EXISTS cv_staff(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL,title TEXT NOT NULL,region TEXT NOT NULL DEFAULT '',profile_slug TEXT NOT NULL DEFAULT '',salt TEXT NOT NULL,password_hash TEXT NOT NULL,iterations INTEGER NOT NULL DEFAULT 100000,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS cv_staff_sessions(hash TEXT PRIMARY KEY,staff_id TEXT NOT NULL REFERENCES cv_staff(id),expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS cv_staff_sessions_member ON cv_staff_sessions(staff_id,expires_at);
CREATE TABLE IF NOT EXISTS cv_projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',owner_id TEXT NOT NULL REFERENCES cv_staff(id),status TEXT NOT NULL DEFAULT 'active',due_date TEXT NOT NULL DEFAULT '',request_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cv_project_members(project_id TEXT NOT NULL REFERENCES cv_projects(id),staff_id TEXT NOT NULL REFERENCES cv_staff(id),PRIMARY KEY(project_id,staff_id));
CREATE INDEX IF NOT EXISTS cv_project_members_staff ON cv_project_members(staff_id,project_id);
CREATE TABLE IF NOT EXISTS cv_tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES cv_projects(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',owner_id TEXT NOT NULL REFERENCES cv_staff(id),created_by TEXT NOT NULL REFERENCES cv_staff(id),status TEXT NOT NULL DEFAULT 'todo',priority TEXT NOT NULL DEFAULT 'normal',due_date TEXT NOT NULL DEFAULT '',approval_required INTEGER NOT NULL DEFAULT 0,request_key TEXT NOT NULL UNIQUE,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_tasks_project ON cv_tasks(project_id,status,due_date);
CREATE TABLE IF NOT EXISTS cv_team_requests(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES cv_staff(id),title TEXT NOT NULL,body TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'resource',stage TEXT NOT NULL,reviewer_id TEXT NOT NULL REFERENCES cv_staff(id),amount REAL,currency TEXT NOT NULL DEFAULT 'AED',decision_note TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_team_requests_reviewer ON cv_team_requests(reviewer_id,stage,created_at);
CREATE TABLE IF NOT EXISTS cv_workspace_comments(id TEXT PRIMARY KEY,target TEXT NOT NULL,staff_id TEXT NOT NULL REFERENCES cv_staff(id),body TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_workspace_comments_target ON cv_workspace_comments(target,created_at);
CREATE TABLE IF NOT EXISTS cv_workspace_assets(id TEXT PRIMARY KEY,target TEXT NOT NULL,staff_id TEXT NOT NULL REFERENCES cv_staff(id),name TEXT NOT NULL,key TEXT NOT NULL,content_type TEXT NOT NULL,bytes INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_workspace_assets_target ON cv_workspace_assets(target,status);
CREATE TABLE IF NOT EXISTS cv_workspace_activity(id TEXT PRIMARY KEY,target TEXT NOT NULL,staff_id TEXT NOT NULL,action TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_workspace_activity_target ON cv_workspace_activity(target,created_at);
CREATE TABLE IF NOT EXISTS cv_workspace_notifications(id TEXT PRIMARY KEY,staff_id TEXT NOT NULL REFERENCES cv_staff(id),target TEXT NOT NULL,message TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS cv_workspace_notifications_staff ON cv_workspace_notifications(staff_id,read_at,created_at);
CREATE TABLE IF NOT EXISTS cv_artist_pipeline(artist_id TEXT PRIMARY KEY,stage TEXT NOT NULL DEFAULT 'discovered',owner_id TEXT NOT NULL DEFAULT 'louis',notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
